fulfill.run:
const re = $self.address.entire
const STORAGE_KEY = 'devtool_environment_marker'
const DEFAULT_RULES = [
  { pattern: '(\\.|-)(develop|development|dev)(\\d*)?\\.', env: 'Dev' },
  { pattern: '(\\.|-)(testing|sit|qa|test)(\\d*)?\\.', env: 'Test' },
  { pattern: '(\\.|-)(prerelease|staging|stage|stg|pre|pp|st)(\\d*)?\\.', env: 'Stage' },
]
$self.state = $observable({ enabled: false, urlFilters: [], rules: [] })
$self.saveEnvMarker = async (s) => {
  await $chrome.storage.local.set({ [STORAGE_KEY]: { enabled: s.enabled, urlFilters: JSON.parse(JSON.stringify(s.urlFilters || [])), rules: JSON.parse(JSON.stringify(s.rules || [])) } })
}
$self.loadEnvMarker = async () => {
  try {
    const res = await $chrome.storage.local.get(STORAGE_KEY)
    const s = res[STORAGE_KEY]
    if (!s || !s.rules || s.rules.length === 0) {
      $self.state.enabled = false
      $self.state.urlFilters = []
      $self.state.rules = DEFAULT_RULES.map((r) => ({ ...r }))
      await $self.saveEnvMarker($self.state)
    } else {
      $self.state.enabled = !!s.enabled
      $self.state.urlFilters = s.urlFilters || []
      $self.state.rules = s.rules || []
    }
  } catch (e) {
    $logger.error('加载环境标记配置失败', e)
    $message.error('加载环境标记配置失败')
  }
}
$self.getRowIndex = (row) => {
  if (!row) return -1
  return $self.state.rules.findIndex((r) => r.pattern === row.pattern)
}
$self.showAddOrUpdateDialog = (row) => {
  const dialog = $self.query(re + '.editDialog').take()
  if (dialog) {
    dialog.value = row ? { pattern: row.pattern, env: row.env, _originalPattern: row.pattern } : {}
    dialog.setComponentProps({ open: true, title: row ? '编辑环境识别规则' : '新增环境识别规则' })
  }
}
$self.handleMove = async (index, direction) => {
  const list = $self.state.rules.slice()
  const newIndex = direction === 'up' ? index - 1 : index + 1
  if (index < 0 || newIndex < 0 || newIndex >= list.length) return
  const tmp = list[index]
  list[index] = list[newIndex]
  list[newIndex] = tmp
  try {
    await $self.saveEnvMarker({ enabled: $self.state.enabled, urlFilters: $self.state.urlFilters, rules: list })
    $self.state.rules = list
  } catch (e) {
    $message.error('操作失败')
  }
}
$self.handleDeleteRule = async (row) => {
  if (!row) return
  const list = $self.state.rules.filter((r) => r.pattern !== row.pattern)
  try {
    await $self.saveEnvMarker({ enabled: $self.state.enabled, urlFilters: $self.state.urlFilters, rules: list })
    $self.state.rules = list
    $message.success('规则已删除')
  } catch (e) {
    $message.error('删除失败')
  }
}
$effect(() => { $self.loadEnvMarker() }, [])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => { $self.value = rf.state.enabled }, [rf.state.enabled])
$props({
  onChange: async (checked) => {
    try {
      await rf.saveEnvMarker({ enabled: checked, urlFilters: rf.state.urlFilters, rules: rf.state.rules })
      rf.state.enabled = checked
      $message.success(checked ? '环境标记已开启' : '环境标记已关闭')
    } catch (e) {
      $message.error('操作失败')
    }
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  $self.value = en ? '已开启，' + rf.state.rules.length + ' 条规则' : ''
  $self.display = en ? 'visible' : 'none'
}, [rf.state.enabled, rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const en = rf.state.enabled
  $self.value = en ? '' : '已关闭，页面 Title 不显示环境标记'
  $self.display = en ? 'none' : 'visible'
}, [rf.state.enabled])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => rf.showAddOrUpdateDialog(null) })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const idx = rf.getRowIndex(row)
  $self.value = idx >= 0 ? '#' + (idx + 1) : ''
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  $self.value = row ? row.pattern : ''
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const env = (row && row.env) || ''
  const lower = env.toLowerCase()
  let color = 'default'
  if (lower.includes('dev')) color = 'blue'
  else if (lower.includes('test')) color = 'orange'
  else if (lower.includes('st') || lower.includes('stage')) color = 'gold'
  else if (lower.includes('pre') || lower.includes('prod')) color = 'red'
  $self.value = env
  $props({ color: color })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const idx = rf.getRowIndex(row)
  $props({
    disabled: idx <= 0,
    onClick: () => rf.handleMove(idx, 'up'),
  })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$effect(() => {
  const row = $utils.getArrayFieldRow($self, 'ArrayTable')
  const idx = rf.getRowIndex(row)
  $props({
    disabled: idx < 0 || idx >= rf.state.rules.length - 1,
    onClick: () => rf.handleMove(idx, 'down'),
  })
}, [rf.state.rules])

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onClick: () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); rf.showAddOrUpdateDialog(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$props({ onConfirm: async () => { const row = $utils.getArrayFieldRow($self, 'ArrayTable'); await rf.handleDeleteRule(row) } })

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
$props({
  onClick: () => {
    const t = $self.query(re + '.urlFilterSection.urlFilterTable').take()
    if (t) t.value = [...(t.value || []), { hostSuffix: '', urlContains: '' }]
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
$props({
  onClick: () => {
    const row = $utils.getArrayFieldRow($self, 'ArrayTable')
    const t = $self.query(re + '.urlFilterSection.urlFilterTable').take()
    if (!t || !row) return
    const idx = (t.value || []).indexOf(row)
    if (idx >= 0) t.value = t.value.filter((_, i) => i !== idx)
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
const t = $self.query(re + '.urlFilterSection.urlFilterTable').take()
$props({
  onClick: async () => {
    const filters = ((t && t.value) || []).map((f) => ({ hostSuffix: (f.hostSuffix || '').trim(), urlContains: (f.urlContains || '').trim() }))
    if (filters.some((f) => !f.hostSuffix && !f.urlContains)) {
      $message.warning('每条生效 URL 范围至少填写 hostSuffix 或 urlContains 之一')
      return
    }
    try {
      await rf.saveEnvMarker({ enabled: rf.state.enabled, urlFilters: filters, rules: rf.state.rules })
      rf.state.urlFilters = filters
      $message.success('触发生效 URL 范围已保存')
    } catch (e) {
      $message.error('保存失败')
    }
  },
})

const re = $self.address.entire.substring(0, $self.address.entire.lastIndexOf('environmentMarkerSettingsDiv') + 'environmentMarkerSettingsDiv'.length)
const rf = $self.query(re).take()
$props({
  onCancel: () => { $self.componentProps.open = false },
  onOk: () => {
    $self.validate().then(async () => {
      const form = $self.value
      const pField = $self.query($self.address.entire + '.pattern').take()
      try {
        new RegExp(form.pattern)
      } catch (err) {
        if (pField) pField.setFeedback({ type: 'error', messages: ['正则表达式格式有误'] })
        return
      }
      const exists = rf.state.rules.some((r) => r.pattern === form.pattern && r.pattern !== form._originalPattern)
      if (exists) {
        if (pField) pField.setFeedback({ type: 'error', messages: ['该正则已存在，请使用不同的表达式'] })
        return
      }
      const list = rf.state.rules.slice()
      const next = { pattern: form.pattern, env: form.env }
      const isEdit = !!form._originalPattern
      if (isEdit) {
        const idx = list.findIndex((r) => r.pattern === form._originalPattern)
        if (idx >= 0) list[idx] = next
        else list.push(next)
      } else {
        list.push(next)
      }
      try {
        await rf.saveEnvMarker({ enabled: rf.state.enabled, urlFilters: rf.state.urlFilters, rules: list })
        rf.state.rules = list
        $message.success(isEdit ? '规则已更新' : '规则已新增')
        $self.componentProps.open = false
      } catch (e) {
        $message.error('保存失败')
      }
    }).catch((e) => $logger.info('校验失败', e))
  },
})
